class Solution:
    def longestMonotonicSubarray(self, nums: List[int]) -> int:
        lI = 0
        lD = 0
        bestI = 1
        bestD = 1

        for r in range(1, len(nums)):
            if nums[r] < nums[r - 1]:
                bestD = max(bestD, r - lD + 1)
                lI = r
            elif nums[r] > nums[r - 1]:
                bestI = max(bestI, r - lI + 1)
                lD = r
            else:
                lI = r
                lD = r

        return max(bestD, bestI)
